<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_admin();$orders=db()->query("SELECT p.*,u.nome cliente,u.email FROM pedidos p JOIN usuarios u ON u.id=p.usuario_id ORDER BY p.criado_em DESC")->fetchAll();$pageTitle='Pedidos';require dirname(__DIR__).'/includes/header.php';?>
<h1 class="h2 mb-4">Pedidos realizados</h1><?php foreach($orders as $o): ?><div class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between flex-wrap"><div><strong>Pedido #<?= (int)$o['id'] ?></strong> · <?= e($o['cliente']) ?> (<?= e($o['email']) ?>)<div class="small text-secondary"><?= e($o['criado_em']) ?> · <?= e($o['pagamento']) ?> · <?= e($o['status']) ?></div></div><strong><?= money($o['total']) ?></strong></div><?php $s=db()->prepare("SELECT pi.*,p.nome FROM pedido_itens pi JOIN produtos p ON p.id=pi.produto_id WHERE pi.pedido_id=?");$s->execute([$o['id']]);foreach($s->fetchAll() as $it): ?><div class="small border-top mt-2 pt-2"><?= e($it['nome']) ?> × <?= (int)$it['quantidade'] ?> — <?= money($it['preco_unitario']*$it['quantidade']) ?></div><?php endforeach; ?></div></div><?php endforeach; ?><?php if(!$orders): ?><p>Nenhum pedido registrado.</p><?php endif; ?>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>